def calculate_monthly_payment(P, n, annual_interest_rate=0.07):
    monthly_interest_rate = annual_interest_rate / 12
    if monthly_interest_rate == 0:
        return P / n
    else:
        # M = P * [i * (1 + i)^n] / [(1 + i)^n - 1]
        numerator = monthly_interest_rate * (1 + monthly_interest_rate)**n
        denominator = (1 + monthly_interest_rate)**n - 1
        return P * (numerator / denominator)

